Here is a multi-threaded C++ program to approximate the integral value using the rectangle, trapezoid and Simpson's methods:

```cpp
#include <windows.h>
#include <iostream>
#include <random>
#include <chrono>

using namespace std;

double integralValue; 
mutex integralMutex;

double f(double x) {
    return x*x; 
}

DWORD WINAPI rectangleThread(LPVOID lpParam) {
    double a = 0; 
    double b = 1; 
    int n = 10000;
    double h = (b - a) / n;

    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i*h);
    }
    double result = h * sum;

    integralMutex.lock();
    integralValue += result;
    integralMutex.unlock();
}

